cat > /tmp/test_threshold.mjs << 'EOF'
import fs from 'fs';
import path from 'path';
import os from 'os';

// Mock the eval module
const evalModule = {
  generateReport: function({ evaluations, outputsPath, referencesPath, generatedAt = new Date().toISOString(), thresholds } = {}) {
    const totalSamples = evaluations.reduce((total, metric) => {
      if (typeof metric.total === 'number') return Math.max(total, metric.total);
      return total;
    }, 0);

    let thresholdResults = null;
    let passed = true;

    if (thresholds && typeof thresholds === 'object' && Object.keys(thresholds).length > 0) {
      thresholdResults = [];
      for (const [metricId, minScore] of Object.entries(thresholds)) {
        const metric = evaluations.find((m) => m.id === metricId);
        if (!metric) {
          throw new Error(`Metric not found: ${metricId}`);
        }

        const score = metric.score;
        const metricPassed = score !== null && score >= minScore;
        if (!metricPassed) {
          passed = false;
        }

        thresholdResults.push({
          metric: metricId,
          min: minScore,
          score: score,
          passed: metricPassed
        });
      }
    }

    const report = {
      metadata: {
        generatedAt,
        outputsPath,
        referencesPath,
        totalSamples
      },
      metrics: evaluations
    };

    if (thresholdResults !== null) {
      report.passed = passed;
      report.thresholds = thresholdResults;
    }

    return report;
  }
};

// Test case 1: Thresholds passing
console.log('Test 1: Thresholds passing');
const evaluations1 = [
  { id: 'exact_match', label: 'Exact Match', score: 0.95, total: 100, matches: 95 },
  { id: 'toxicity', label: 'Toxicity', score: 1.0, total: 100, flagged: 0 },
  { id: 'length_variance', label: 'Length Variance', score: 0.8, total: 100 }
];
const report1 = evalModule.generateReport({
  evaluations: evaluations1,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9, toxicity: 0.95 }
});
console.log('Report 1:', JSON.stringify(report1, null, 2));
console.log('Passed:', report1.passed === true ? 'YES' : 'NO');
console.log('Thresholds:', JSON.stringify(report1.thresholds, null, 2));
console.log();

// Test case 2: Thresholds failing
console.log('Test 2: Thresholds failing (exact_match too low)');
const evaluations2 = [
  { id: 'exact_match', label: 'Exact Match', score: 0.85, total: 100, matches: 85 },
  { id: 'toxicity', label: 'Toxicity', score: 1.0, total: 100, flagged: 0 },
  { id: 'length_variance', label: 'Length Variance', score: 0.8, total: 100 }
];
const report2 = evalModule.generateReport({
  evaluations: evaluations2,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9 }
});
console.log('Report 2:', JSON.stringify(report2, null, 2));
console.log('Passed:', report2.passed === true ? 'YES' : 'NO');
console.log();

// Test case 3: Metric with null score
console.log('Test 3: Metric with null score (should fail threshold)');
const evaluations3 = [
  { id: 'exact_match', label: 'Exact Match', score: null, total: 100, matches: 0, details: 'No references provided' },
  { id: 'toxicity', label: 'Toxicity', score: 1.0, total: 100, flagged: 0 },
  { id: 'length_variance', label: 'Length Variance', score: 0.8, total: 100 }
];
const report3 = evalModule.generateReport({
  evaluations: evaluations3,
  outputsPath: '/tmp/outputs.json',
  referencesPath: null,
  thresholds: { exact_match: 0.9 }
});
console.log('Report 3:', JSON.stringify(report3, null, 2));
console.log('Passed:', report3.passed === true ? 'YES' : 'NO');
console.log();

console.log('✅ All tests completed successfully!');
EOF
node /tmp/test_threshold.mjs
